typedef struct Tok {
    int64_t refcnt;
    hl_str* f_kind;
    hl_str* f_value;
    int64_t f_line;
    int64_t f_col;
} Tok;

static Tok* usf_new_Tok(hl_str* f_kind, hl_str* f_value, int64_t f_line, int64_t f_col) {
    Tok* p = (Tok*)malloc(sizeof(Tok));
    if (!p) hl_die("out of memory");
    p->refcnt = 1;
    p->f_kind = f_kind;
    p->f_value = f_value;
    p->f_line = f_line;
    p->f_col = f_col;
    return p;
}

static void hl_release_Tok(void* pv) {
    Tok* p = (Tok*)pv;
    if (!p) return;
    if (--p->refcnt == 0) {
        hl_str_release(p->f_kind);
        hl_str_release(p->f_value);
        free(p);
    }
}
static void hl_cleanup_Tok(Tok** p) { hl_release_Tok(*p); }

