static void hl_release_StmtN(void* pv) {
    StmtN* p = (StmtN*)pv;
    if (!p) return;
    if (--p->refcnt == 0) {
        hl_str_release(p->f_kind);
        hl_str_release(p->f_name);
        hl_str_release(p->f_vtype);
        hl_list_release(p->f_body);
        hl_list_release(p->f_else_body);
        hl_str_release(p->f_asm_template);
        hl_list_release(p->f_asm_operands);
        hl_list_release(p->f_asm_options);
        hl_list_release(p->f_asm_clobbers);
        hl_str_release(p->f_rpred);
        free(p);
    }
}
static void hl_cleanup_StmtN(StmtN** p) { hl_release_StmtN(*p); }

